"""ใส่ SN (จากบิล FlexxFast) ให้ตู้ชาร์จที่ sync_stations_from_excel.py สร้างใหม่ — dry-run ก่อน, --apply เพื่อเขียนจริง
   ใส่เฉพาะตู้ DC ที่ SN ยังว่าง, ข้าม SN ที่มีในระบบแล้ว, หลายตู้จับคู่ด้วยกำลังไฟ (F150… = 150kW)"""
import os, re, sys
from pymongo import MongoClient
APPLY = "--apply" in sys.argv
ACTOR = "import:sync_stations_from_excel"
# รหัส Maximo ของสถานี : SN จากบิล FlexxFast (หลายตู้คั่นด้วย +)
RAW = "EGT0017:F1501124003 EGT0029:F1501224001 EGT0071:F1500425013 EGT0179:F1200224003 EGT0182:F1200124001 EGT0183:F1200224002 EGT0327:F1500425005 EGT0328:F1500225011 EGT0329:F1500425033 PTG0001:F1500425016 PTG0002:F1500425032 PTG0003:F1501224046 PTG0004:F1500425034 PTG0005:F1500425017 PTG0050:F1500425019 PTG0164:F1500224003 PTG0165:F1500124002 PTG0166:F1500224005 PTG0168:F1500224002 PTG0169:F1500224001 PTG0170:F1500124001 PTG0171:F1500224006 PTG0172:F1500324001 PTG0173:F1500224004 PTG0174:F15003240012 PTG0175:F1501223002 PTG0176:F1501223003 PTG0177:F1501223001 PTG0178:F1501223004 PTG0186:F1500824002 PTG0187:F1500624029 PTG0188:F1500724020 PTG0190:F1500724010 PTG0191:F1500824020 PTG0192:F1500724011 PTG0193:F1500824001 PTG0194:F1500624008 PTG0195:F1500824026 PTG0197:F1500624007 PTG0198:F1500624010 PTG0199:F1500824024 PTG0200:F1500824023 PTG0201:F1500824025 PTG0202:F1500624003 PTG0203:F1500624004 PTG0204:F1500724013 PTG0205:F1500724019 PTG0207:F1500624006 PTG0208:F1500824027 PTG0209:F1500724016 PTG0210:F1500724009 PTG0211:F1500724008 PTG0212:F1500724012 PTG0213:F1500824021 PTG0214:F1500824022 PTG0215:F1500624009 PTG0217:F1500724007 PTG0218:F1500624013 PTG0219:F1500624026 PTG0220:F1500624042 PTG0221:F1500624015 PTG0222:F1500624016 PTG0223:F1500624024 PTG0224:F1500624040 PTG0226:F1500624023 PTG0227:F1500624039 PTG0228:F1500624028 PTG0229:F1500624019 PTG0230:F1500724006 PTG0231:F1500724002 PTG0232:F1500724003 PTG0233:F1500724001 PTG0234:F1500624017 PTG0235:F1500724005 PTG0236:F1500624011 PTG0237:F1500624038 PTG0238:F1500624012 PTG0239:F1500624022 PTG0240:F1500624021 PTG0241:F1500624041 PTG0242:F1500624043 PTG0243:F1500624037 PTG0244:F1500624018 PTG0245:F1500624014 PTG0246:F1500624030 PTG0247:F1501223005 PTG0248:F1500824011 PTG0249:F1500824004 PTG0250:F1500624059 PTG0251:F1500624060 PTG0252:F1500724023 PTG0253:F1500724032 PTG0255:F1500824014 PTG0256:F1500724038 PTG0257:F1500824010 PTG0258:F1500824005 PTG0259:F1500624056 PTG0260:F1500724026 PTG0261:F1500824006 PTG0262:F1500724024 PTG0263:F1500724037 PTG0264:F1500724029 PTG0265:F1500624054 PTG0266:F1500624048 PTG0267:F1500724035 PTG0268:F1500824015 PTG0271:F1500724036 PTG0272:F1500824016 PTG0273:F1500724033 PTG0274:F1500624050 PTG0276:F1500724034 PTG0277:F1500724031 PTG0278:F1500624035 PTG0279:F1500824013 PTG0280:F1500624034 PTG0281:F1500624027 PTG0282:F1500724022 PTG0283:F1500824028 PTG0284:F1500624032 PTG0285:F1500624031 PTG0286:F1500724025 PTG0287:F1500624020 PTG0289:F1500824019 PTG0290:F1500824007 PTG0291:F1500824018 PTG0292:F1500624061 PTG0293:F1500824017 PTG0294:F1500724018 PTG0295:F1500624036 PTG0296:F1500824009 PTG0297:F1500824008 PTG0298:F1500724015 PTG0299:F1500724014 PTG0300:F1500824030 PTG0302:F1500724021 PTG0303:F1500824003 PTG0304:F1500824012 PTG0305:F1501224004 PTG0306:F1500824029 PTG0307:F1501224005 PTG0308:F1500724004 PTG0309:F1501224008 PTG0311:F1501124008 PTG0312:F1500624058 PTG0313:F1501224002 PTG0314:F1500624055 PTG0315:F1501224003 PTG0316:F1500624062 PTG0317:F1500624047 PTG0318:F1500324003 PTG0319:F1500624025 PTG0320:F1500624052 PTG0321:F1501224009 PTG0322:F1501224006 PTG0323:F1500624044 PTG0324:F1500624049 PTG0325:F1500225004+F1500225005+F1500225006"
SN = {c: v.split("+") for c, v in (x.split(":") for x in RAW.split())}
db = MongoClient(os.environ["MONGO_URI"])["iMPS"]
used = {c["SN"].strip() for c in db.charger.find({"SN": {"$nin": ["", None]}}, {"SN": 1})}
kw = lambda s: re.match(r"F(\d{3})", s).group(1).lstrip("0")
sets, skip = [], []
for st in db.stations.find({"createdBy": ACTOR}, {"station_id": 1, "maximo_location": 1}):
    sns = [s for s in SN.get((st.get("maximo_location") or "").split("-EV")[0], []) if s not in used]
    if not sns:
        continue
    dc = [c for c in db.charger.find({"station_id": st["station_id"], "createdBy": ACTOR, "SN": ""}).sort("chargerNo", 1)
          if (c.get("chargerType") or "DC").upper() == "DC"]
    if len(dc) == 1 and len(sns) == 1:
        pairs = [(dc[0], sns[0])]
    else:
        pairs = []
        for s in sns:
            cand = [c for c in dc if str(c.get("power") or "").split(".")[0] == kw(s) and c not in [p[0] for p in pairs]]
            if len(cand) == 1: pairs.append((cand[0], s))
            else: skip.append(f"{st['station_id']}: SN {s} จับคู่ตู้ไม่ได้ (ตู้ DC {len(dc)} ตู้)")
    for c, s in pairs:
        note = "" if str(c.get("power") or "").split(".")[0] == kw(s) else f"  ⚠ กำลังไฟตู้ {c.get('power')}kW ≠ SN {kw(s)}kW"
        sets.append((c["_id"], s)); used.add(s)
        print(f"[SN] {st['station_id']} ตู้ {c.get('chargerNo')} {c.get('charger_name')} ← {s}{note}")
for x in skip: print("[ข้าม]", x)
print(f"\n[i] จะใส่ SN {len(sets)} ตู้, ข้าม {len(skip)}")
if not APPLY:
    print("[i] dry-run — รันซ้ำโดยเปลี่ยน 'python3 -' เป็น 'python3 - --apply'"); sys.exit()
for oid, s in sets:
    db.charger.update_one({"_id": oid, "SN": ""}, {"$set": {"SN": s}})
print(f"[✓] ใส่ SN แล้ว {len(sets)} ตู้")
